<?php

namespace App\Services\Apply;

use App\Models\ApplicationDraft;
use App\Models\CareerProfile;
use App\Models\JobListing;
use App\Models\Resume;
use App\Services\JobSources\AtsBoardRegistry;
use Illuminate\Support\Facades\Http;

/**
 * Lever Postings API: POST /v0/postings/{site}/{id}?key=KEY. The key is
 * generated by a Super Admin at the employer (the postings API's apply
 * endpoint is rate-limited to 2 POSTs/second), so only boards listed in
 * LEVER_SITE_KEYS are supported.
 */
class LeverApiDriver implements ApplyDriver
{
    public function channel(): string
    {
        return 'lever_api';
    }

    private function key(JobListing $job): ?string
    {
        return AtsBoardRegistry::keys('lever_keys')[strtolower((string) $job->ats_board)] ?? null;
    }

    public function supports(JobListing $job): bool
    {
        return $job->ats === 'lever' && $job->ats_board && $job->ats_job_id && $this->key($job);
    }

    public function submit(JobListing $job, ApplicationDraft $draft, Resume $resume, CareerProfile $profile, string $resumePdfPath): ApplyResult
    {
        try {
            $fields = array_filter([
                'name' => $resume->full_name,
                'email' => $resume->email,
                'phone' => $resume->phone,
                'org' => $resume->experiences->first()?->company,
                'comments' => $draft->cover_letter,
                'urls[LinkedIn]' => $resume->linkedin_url,
                'urls[GitHub]' => $resume->github_url,
                'urls[Portfolio]' => $resume->website_url,
            ]);

            $payload = [];
            foreach ($fields as $k => $v) {
                $payload[] = ['name' => $k, 'contents' => (string) $v];
            }

            $res = Http::timeout(60)->asMultipart()
                ->attach('resume', file_get_contents($resumePdfPath), basename($resumePdfPath))
                ->post("https://api.lever.co/v0/postings/{$job->ats_board}/{$job->ats_job_id}?key=" . urlencode($this->key($job)), $payload);

            if ($res->successful()) {
                return ApplyResult::submitted($res->json('applicationId') ?? $job->ats_job_id);
            }

            // Custom-question postings reject with a 4xx naming what's missing:
            // surface that as needs_input rather than a blind retry.
            if ($res->status() === 400 && stripos($res->body(), 'required') !== false) {
                return ApplyResult::needsInput([mb_substr($res->body(), 0, 300)]);
            }

            return ApplyResult::failed("Lever rejected the application (HTTP {$res->status()}): " . $res->body());
        } catch (\Throwable $e) {
            return ApplyResult::failed($e->getMessage());
        }
    }
}
